import {createRequire} from 'node:module';
const require = createRequire('/tmp/pw/node_modules/');
const {chromium} = require('playwright');

const out = process.argv[2];
const browser = await chromium.launch();
const page = await browser.newPage({viewport: {width: 1200, height: 800}});
const errors = [];
page.on('console', (m) => (m.type() === 'error' || m.type() === 'warning') && errors.push(m.text()));
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));

await page.goto('http://localhost:5179/theme-check.html');
await page.waitForSelector('.cpu-load-chart canvas', {timeout: 10000});
await page.waitForTimeout(1500);
const info = await page.evaluate(() => ({
  canvases: document.querySelectorAll('.cpu-load-chart canvas').length,
  uplots: document.querySelectorAll('.uplot').length,
  tooltips: document.querySelectorAll('.yagr-tooltip').length,
  value: document.querySelector('.cpu-card__value')?.textContent,
  plotSize: (() => { const r = document.querySelector('.cpu-load-chart__plot').getBoundingClientRect(); return [r.width, r.height]; })(),
  canvasSize: (() => { const c = document.querySelector('.cpu-load-chart canvas'); return [c.clientWidth, c.clientHeight]; })(),
  infoColor: getComputedStyle(document.querySelector('.cpu-load-chart .yagr')).getPropertyValue('--g-color-text-info'),
}));
console.log('initial', JSON.stringify(info));
await page.screenshot({path: `${out}/light.png`});

// hover tooltip
const box = await page.locator('.cpu-load-chart .u-over').boundingBox();
await page.mouse.move(box.x + box.width * 0.6, box.y + box.height * 0.5);
await page.waitForTimeout(1300); // survive at least one live update
console.log('tooltip visible after live update:', await page.evaluate(() => { const t = document.querySelector('.yagr-tooltip'); return t && getComputedStyle(t).display; }));
await page.screenshot({path: `${out}/light-hover.png`});

// zoom by drag
await page.mouse.move(box.x + box.width * 0.3, box.y + 50);
await page.mouse.down();
await page.mouse.move(box.x + box.width * 0.4, box.y + 60, {steps: 5});
await page.mouse.up();
await page.waitForTimeout(2500);
console.log('zoom button:', await page.getByText('Сбросить масштаб').count());
await page.mouse.move(10, 10);
await page.screenshot({path: `${out}/zoomed.png`});
await page.getByText('Сбросить масштаб').click();
await page.waitForTimeout(300);
console.log('zoom button after reset:', await page.getByText('Сбросить масштаб').count());

// theme
await page.evaluate(() => window.__setTheme('dark'));
await page.waitForTimeout(500);
console.log('dark info color', await page.evaluate(() => getComputedStyle(document.querySelector('.cpu-load-chart .yagr')).getPropertyValue('--g-color-text-info')));
await page.mouse.move(box.x + box.width * 0.8, box.y + box.height * 0.5);
await page.waitForTimeout(300);
await page.screenshot({path: `${out}/dark-hover.png`});
await page.mouse.move(10, 10);

// resize
await page.setViewportSize({width: 700, height: 900});
await page.waitForTimeout(400);
console.log('resized', await page.evaluate(() => { const c = document.querySelector('.cpu-load-chart canvas'); const r = document.querySelector('.cpu-load-chart__plot').getBoundingClientRect(); return [c.clientWidth, c.clientHeight, r.width, r.height]; }));
await page.screenshot({path: `${out}/dark-narrow.png`});

// perf: time per flush & long tasks
const perf = await page.evaluate(async () => {
  const lt = [];
  const po = new PerformanceObserver((l) => l.getEntries().forEach((e) => lt.push(e.duration)));
  po.observe({type: 'longtask', buffered: false});
  await new Promise((r) => setTimeout(r, 4000));
  po.disconnect();
  return {longTasks: lt};
});
console.log('perf', JSON.stringify(perf), 'points', await page.evaluate(() => document.querySelector('.cpu-load-chart .uplot') && 'ok'));

// unmount
await page.evaluate(() => window.__setMounted(false));
await page.waitForTimeout(500);
console.log('after unmount', JSON.stringify(await page.evaluate(() => ({
  uplots: document.querySelectorAll('.uplot').length,
  tooltips: document.querySelectorAll('.yagr-tooltip').length,
}))));
await page.waitForTimeout(1500);
console.log('errors', JSON.stringify(errors));
await browser.close();
EOF
