import {createRequire} from 'node:module';
const require = createRequire('/tmp/pw/node_modules/');
const {chromium} = require('playwright');
const browser = await chromium.launch();
const page = await browser.newPage({viewport: {width: 1400, height: 700}});
await page.goto(`http://localhost:5179/theme-check.html?step=${process.argv[2]}`);
await page.waitForSelector('.cpu-load-chart canvas');
await page.waitForTimeout(500);
const cdp = await page.context().newCDPSession(page);
await cdp.send('Profiler.enable');
await cdp.send('Profiler.setSamplingInterval', {interval: 100});
await cdp.send('Profiler.start');
await page.waitForTimeout(6000);
const {profile} = await cdp.send('Profiler.stop');
const self = new Map();
const byId = new Map(profile.nodes.map((n) => [n.id, n]));
const dt = profile.timeDeltas; const counts = new Map();
profile.samples.forEach((id, i) => counts.set(id, (counts.get(id) || 0) + (dt[i] || 0)));
for (const [id, t] of counts) { const n = byId.get(id); const cf = n.callFrame; const key = `${cf.functionName || '(anon)'} ${cf.url.split('/').pop().split('?')[0]}:${cf.lineNumber}`; self.set(key, (self.get(key) || 0) + t); }
[...self.entries()].filter(([k]) => !k.startsWith('(idle)') && !k.startsWith('(program)')).sort((a, b) => b[1] - a[1]).slice(0, 18).forEach(([k, t]) => console.log((t / 1000).toFixed(1).padStart(7), 'ms', k));
await browser.close();
EOF
