import {createRequire} from 'node:module';
const require = createRequire('/tmp/pw/node_modules/');
const {chromium} = require('playwright');

const out = process.argv[2];
const browser = await chromium.launch();
const page = await browser.newPage({viewport: {width: 1200, height: 800}});
const errors = [];
page.on('console', (m) => (m.type() === 'error' || m.type() === 'warning') && errors.push(m.text()));
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));

await page.goto('http://localhost:5179/theme-check.html');
await page.waitForSelector('.cpu-load-chart canvas', {timeout: 10000});
await page.waitForTimeout(1500);
const info = await page.evaluate(() => ({
  canvases: document.querySelectorAll('.cpu-load-chart canvas').length,
  uplots: document.querySelectorAll('.uplot').length,
  tooltips: document.querySelectorAll('.yagr-tooltip').length,
  value: document.querySelector('.cpu-card__value')?.textContent,
  plotSize: (() => { const r = document.querySelector('.cpu-load-chart__plot').getBoundingClientRect(); return [r.width, r.height]; })(),
  canvasSize: (() => { const c = document.querySelector('.cpu-load-chart canvas'); return [c.clientWidth, c.clientHeight]; })(),
  infoColor: getComputedStyle(document.querySelector('.cpu-load-chart .yagr')).getPropertyValue('--g-color-text-info'),
}));
console.log('initial', JSON.stringify(info));
await page.screenshot({path: `${out}/light.png`});

// hover tooltip
const box = await page.locator('.cpu-load-chart .u-over').boundingBox();
await page.mouse.move(box.x + box.width * 0.6, box.y + box.height * 0.5);
await page.waitForTimeout(1300); // survive at least one live update
console.log('tooltip visible after live update:', await page.evaluate(() => { const t = document.querySelector('.yagr-tooltip'); return t && getComputedStyle(t).display; }));
await page.screenshot({path: `${out}/light-hover.png`});

// zoom by drag
await page.mouse.move(box.x + box.width * 0.3, box.y + 50);
await page.mouse.down();
await page.mouse.move(box.x + box.width * 0.4, box.y + 60, {steps: 5});
await page.mouse.up();
await page.waitForTimeout(2500);
console.log('zoom button:', await page.getByText('Сбросить масштаб').count());
await page.mouse.move(10, 10);
